#else
#define debug(...)
#define debugArr(...)
#endif
pair<int, int> from, dest;
const int maxn = 105;
int dist[maxn][maxn][4]; 
struct Cell {
    int i, j;
    int type;
};
struct Node {
    int i, j;
    int cost;
    int hp;
    Node(int i, int j, int cost, int hp) : i(i), j(j), cost(cost), hp(hp) {}
    Node transfer(Cell target) {
        if(target.type == 1) {
            return Node(target.i, target.j, cost + 1, hp);
        } else if(target.type == -1) {
            return Node(target.i, target.j, cost + 1, hp - 1);
        }
        return Node(target.i, target.j, cost + 1, hp);
    }
    bool operator>(const Node &other) const {
        return tie(cost, hp) > tie(other.cost, other.hp); 
    }
};

int dx[4] = {-1, 1, 0, 0};
int dy[4] = {0, 0, -1, 1};
Cell a[maxn][maxn];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    for(int i = 1; i <= n; i++) {
        for(int j = 1; j <= m; j++) {
            char c;
            cin >> c;
            a[i][j].i = i;
            a[i][j].j = j;
            if(c == '-') {
                a[i][j].type = 1;
            } else if(c == '+') {
                a[i][j].type = -1;
            } else if(c == 'D') {
                dest = {i, j};
                a[i][j].type = 0;
            } else {
                from = {i, j};
                a[i][j].type = 0;
            }
        }
    }

    memset(dist, 0x3f, sizeof(dist));
    priority_queue<Node, vector<Node>, greater<Node>> pq;
    pq.push(Node(from.first, from.second, 0, 3));
    dist[from.first][from.second][3] = 0;

    while(!pq.empty()) {
        Node cur = pq.top();
        pq.pop();

        if(cur.i == dest.first && cur.j == dest.second) {
            cout << cur.cost << "\n";
            return 0;
        }

        for(int d = 0; d < 4; d++) {
            int x = dx[d] + cur.i;
            int y = dy[d] + cur.j;
            if(!(1 <= x && x <= n && 1 <= y && y <= m)) continue;

            Node nxt = cur.transfer(a[x][y]);
            if(nxt.hp <= 0) continue;
            if(dist[nxt.i][nxt.j][nxt.hp] > nxt.cost) {
                dist[nxt.i][nxt.j][nxt.hp] = nxt.cost;
                pq.push(nxt);
            }
        }
    }

    cout << "-1\n"; 
}